export const windowsMeta={slug:'algorithms/windows',title:'Pointers and Sliding Windows',description:'Prove boundary movement: sorted pairs, compaction, center expansion, fixed and variable windows, requirement counts and signed-sum failures.',date:'2026-07-24',updated:'2026-10-10',topicPath:['algorithms'],tags:['two pointers','sliding window','invariant','contiguous','at most K','monotonicity','palindrome'],prototype:true,visibility:'public',kind:'dense-topic',learningGoals:['Prove safe pointer movement.','Implement fixed and variable window contracts.','Recognize failures of signed-sum monotonicity.'],related:['algorithms/arrays','algorithms/stacks','algorithms/linked-lists']};
export const windowsAliases=[];
export const windowsSections=[['movement','The proof comes before the pointers'],['pairs','Eliminate impossible pairs in sorted order'],['pair-lab','Why this boundary may move'],['compaction','Read/write pointers preserve a prefix'],['centers','Centers, merges and a fixed outer choice'],['center-code','Expand one palindrome center'],['fixed','Reuse a fixed contiguous range'],['variable','Longest and shortest use different loops'],['unique-code','Compute the longest unique substring length'],['unique-lab','Restore validity before recording length'],['requirements','Track satisfied frequency requirements'],['coverage-lab','Record coverage before removing'],['counting','Exactly K through at-most counts'],['counting-code','Count ranges with at most K distinct values'],['failure','Where forward-only boundaries fail'],['practice','State the window and the cost model'],['sources','Connected patterns']];
const pairInput=[1,2,4,7,11,15],pairs=pairTrace(pairInput,15),text='abca',unique=uniqueTrace(text);
const table=(caption,heads,rows)=>baseTable(caption,heads,rows).replace('class="dense-table-wrap"',`class="dense-table-wrap" tabindex="0" role="region" aria-label="${caption}"`).replace('<table>',`<table style="min-width:${caption==='Required counts, not just character presence'?350:640}px">`);
const coverInput='CAAABA',cover=coverTrace(coverInput,'AAB');
const coverBody=f=>`${cells([...coverInput],Array.from({length:Math.max(0,f.right-f.left+1)},(_,i)=>f.left+i))}<p>${f.event}</p>${table('Required counts, not just character presence',['Character','Need','Current','Satisfied'],[['A',2,new Map(f.counts).get('A')||0,(new Map(f.counts).get('A')||0)>=2?'yes':'no'],['B',1,new Map(f.counts).get('B')||0,(new Map(f.counts).get('B')||0)>=1?'yes':'no']])}<p>Satisfied requirements: ${f.formed}/${f.required}. ${f.finished?'Scan complete: no input remains.':f.formed===f.required?'Covered: record before removing.':'Not covered: expand again.'} Best recorded range: ${f.best?`[${f.best}] = “${[...coverInput].slice(f.best[0],f.best[1]+1).join('')}”, length ${f.best[1]-f.best[0]+1}`:'none'}.</p>`;
const pairBody=f=>`${cells(pairInput,f.left<f.right?[f.left,f.right]:[])}<p>${f.move==='found'?`${pairInput[f.left]} + ${pairInput[f.right]} = 15. Found distinct indices ${f.left}, ${f.right}.`:f.move==='none'?'No distinct pair remains.':f.move==='left'?`${f.sum} &lt; 15: even the largest eligible partner is too small for index ${f.left}. Discard that left index.`:`${f.sum} &gt; 15: even the smallest eligible partner is too large for index ${f.right}. Discard that right index.`}</p><p>This frame shows the compared boundaries. The next step applies the justified move.</p>`;
const uniqueBody=f=>`${cells([...text],f.right>=f.left?Array.from({length:f.right-f.left+1},(_,i)=>f.left+i):[])}<p>${f.event}</p><div class="scene-stats"><span>Left <output>${f.left}</output></span><span>Right <output>${f.right}</output></span><span>Best valid length <output>${f.best}</output></span></div><p>Counts in current window: ${f.counts.map(([c,n])=>`${c}:${n}`).join(' · ')||'empty'}. ${f.counts.some(([,n])=>n>1)?'Currently invalid: do not record its length.':'Currently unique.'}</p>`;
export function windowsReader(link){return topic(windowsMeta,windowsSections,'Move a boundary only when its invariant makes the move safe.',`
<p>Two indices are not an algorithm by themselves. They become useful when a move eliminates impossible candidates, preserves a compacted prefix or updates one contiguous range without rescanning it.</p><p>The first question is not “can I use two pointers?” It is “what lets me move one without losing a valid answer?” Sorted order and monotone window validity provide different proofs. Do not transfer a movement rule between them without checking its conditions.</p>
${section('movement','The proof comes before the pointers',table('Different reasons to use two indices',['Structure','What is maintained','Why progress is safe'],[['Opposite ends','Eligible pair interval','Sorted values bound every partner on one side'],['Read/write','Accepted output prefix','Write never overwrites unread input'],['Fixed window','Last k items and their state','Add entering item; remove leaving item'],['Variable window','Valid or newly valid contiguous range','Discarded starts cannot improve the objective later'],['Center expansion','Matched palindrome interior','Only adjacent matching characters extend this center'],['Fast/slow','Traversal state','A separate cycle/meeting proof; not ordinary window validity']]))}
${section('pairs','Eliminate impossible pairs in sorted order',`<p>For sorted nondecreasing a, compare a[left]+a[right]. If the sum is below target, every eligible partner at or below right is also too small for that left value. Move left forward. If it is above target, every eligible partner at or above left is too large for that right value. Move right backward.</p><pre tabindex="0" role="region" aria-label="Sorted pair detection Python"><code>def has_pair_with_sum(nums, target):
    left, right = 0, len(nums) - 1
    while left &lt; right:
        total = nums[left] + nums[right]
        if total == target: return True
        if total &lt; target: left += 1
        else: right -= 1
    return False</code></pre><p>The function returns existence, not indices. Return the two current indices instead of True if positions are required. left&lt;right enforces distinct elements. On unsorted input, these bounds do not hold. Sorting can make them valid but costs work, changes order and loses original indices unless those indices travel with their values. <a href="${link('algorithms/arrays')}">Complement hashing →</a> avoids this sorted-order requirement.</p>${traceLab('pair-lab','Why this boundary may move','Sorted [1,2,4,7,11,15], target 15. Only one boundary moves when its whole row or column of possible partners is ruled out.',pairs,pairs.length-1,pairBody)}`)}
${section('compaction','Read/write pointers preserve a prefix',`<p>Read visits each original value; write is the next free output position. After handling the read position, the prefix before write contains exactly the accepted values in their required order. For sorted duplicate removal, adjacent equal values belong to one run.</p><pre tabindex="0" role="region" aria-label="Sorted compaction Python"><code>def remove_duplicates(nums):
    write = 0
    for read in range(len(nums)):
        if write == 0 or nums[read] != nums[write - 1]:
            nums[write] = nums[read]
            write += 1
    return write</code></pre><p>Writing at or behind read protects unread data. The function handles empty input and returns a logical length; it does not promise that the original container shrinks. On unsorted data it removes only adjacent repetitions, not every repeated value.</p><p>Fast/slow pointers solve a different family: linked-list cycle detection or a processed boundary. Relative motion on a cycle provides the meeting argument. Do not assume that moving at two speeds solves an arbitrary array relation.</p>`)}
${section('centers','Centers, merges and a fixed outer choice',`<p>A palindrome grows around either one character (odd length) or the gap between two characters (even length). Expand while both indices are in bounds and characters match. On stopping, [left+1,right) is the valid palindrome. Trying all centers takes O(n²) time in the worst case, not one globally linear scan.</p><details id="center-code"><summary>Expand one odd or even palindrome center</summary><pre tabindex="0" role="region" aria-label="Palindrome expansion Python"><code>def expand(s, left, right):
    while left &gt;= 0 and right &lt; len(s) and s[left] == s[right]:
        left -= 1
        right += 1
    return s[left + 1:right]</code></pre><p>Call with a valid odd center (i,i) or even center (i,i+1). The even center at the final position has right equal to the string length and returns an empty string. Python strings are indexed by Unicode code point; this does not define grapheme-cluster or normalized palindrome equality. Each returned slice allocates its characters.</p></details><p>To merge two ordered inputs, compare their current heads and consume the smaller eligible value. Each item is consumed once; output size matters. For a three-value sum, fix one sorted position and apply opposite-end reasoning to its suffix. Repeating a linear suffix scan gives O(n²) overall.</p><p>When producing unique value triples, record a valid triple before skipping equal runs. When producing index triples, skipping equal values may discard required outputs. State what makes two answers distinct.</p><p>The shorter-boundary move in maximum container area uses another bound: reducing width cannot help while keeping the current shorter height. Trapping water uses known boundary maxima. Neither follows solely from the sum comparison rule; a superficially similar pair of pointers can require a different invariant.</p>`)}
${section('fixed','Reuse a fixed contiguous range',`<p>A fixed-size window is a contiguous range, not an arbitrary subsequence. For sums, add the new right value and remove the item falling out of the left boundary. Record only once k items exist. Validate ${inlineMath("1\\le k\\le n")} or define an explicit no-window result.</p><pre tabindex="0" role="region" aria-label="Fixed window sum Python"><code>def max_sum_of_size_k(nums, k):
    if type(k) is not int or not 1 &lt;= k &lt;= len(nums):
        raise ValueError('window size outside input')
    total, best = 0, float('-inf')
    for right, value in enumerate(nums):
        total += value
        if right &gt;= k:
            total -= nums[right - k]
        if right &gt;= k - 1:
            best = max(best, total)
    return best</code></pre><p>This implementation rejects an invalid window size rather than returning a numeric sentinel for no window. After adjustment during startup, the state describes at most k items; after startup it describes exactly k. Initializing best to zero would be wrong when every complete window has negative sum. Negative values do not invalidate this fixed-size additive update.</p><p>Maximum does not support removal by subtraction. A sliding maximum needs another structure, such as a monotonic deque that removes expired indices from the front and dominated candidates from the back. Counts require decrementing the outgoing value; a full recomputation defeats the reuse.</p>`)}
${section('variable','Longest and shortest use different loops',`<p>For the longest unique substring, expand right, then repeatedly remove from left while a duplicate exists. Record only after restoring uniqueness. Before expansion the window is unique, so only the entering character can newly violate that condition.</p><details id="unique-code"><summary>Compute the longest unique substring length</summary><pre tabindex="0" role="region" aria-label="Unique substring window Python"><code>def longest_unique_substring(s):
    counts = {}
    left = best = 0
    for right, char in enumerate(s):
        counts[char] = counts.get(char, 0) + 1
        while counts[char] &gt; 1:
            departing = s[left]
            counts[departing] -= 1
            left += 1
        best = max(best, right - left + 1)
    return best</code></pre><p>Zero-count keys may remain because this validity check reads the entering character's count, not dictionary size. The map can retain all characters seen so far. If validity instead uses the number of current distinct keys, remove a key when its count reaches zero.</p></details><p>For a shortest covering range, expand until all requirements are met, record that valid range, then shrink while it remains valid. The last removal can break validity; do not record an invalid range afterward.</p>${table('Order of operations',['Objective','Shrink when','Record when'],[['Longest valid range','Invalid','After validity is restored'],['Shortest covering range','Valid','Before a removal might break coverage']])}<p>Each removal needs a reason it can never become a better start for a later right boundary. A duplicate-containing range cannot become unique by appending more characters. Once a covering range at one start has been recorded, extending that same start only makes it longer.</p>${traceLab('unique-lab','Restore validity before recording length','Code-point sequence “abca”. Adding the second a makes a length-four invalid window. Remove the first a before accepting the new length-three range.',unique,unique.length-1,uniqueBody)}`)}
${section('requirements','Track satisfied frequency requirements',`<p>For covering a target multiset, keep required counts, current counts and formed: the number of distinct required characters whose count has reached its requirement. Increase formed only when an added required count crosses from need−1 to need; decrease it when removal crosses from need to need−1. Surplus copies do not add another satisfied requirement.</p><p>For target “AAB”, {A:1,B:1} is not coverage. {A:2,B:1} is. A scalar avoids comparing whole dictionaries after every move, but its crossing logic must still preserve exact multiplicities.</p>${traceLab('coverage-lab','Record coverage before removing','Synthetic code-point sequence “CAAABA”, target multiset “AAB”. Record “CAAAB”, then remove C and one surplus A without losing coverage. Record “AAB” at [2,4] before the next A removal breaks coverage. The later “ABA” ties its length; keep the earlier range.',cover,cover.findIndex(f=>f.event.startsWith('Coverage holds')),coverBody)}<p>A fixed-length anagram window can maintain requirement differences or a mismatch count. Delete zero-count keys if dictionary size represents distinct characters. A stale maximum frequency is safe in certain replacement-length algorithms only with that algorithm's proof; it is not an exact summary of every current window.</p>`)}
${section('counting','Exactly K through at-most counts',`${eq("C_{=K}=C_{\\le K}-C_{\\le K-1},\\qquad K\\in\\mathbb Z_{\\ge0}","Counts refer to the same universe of nonempty ranges, classified by a nonnegative integer statistic. Define C≤k=0 for k&lt;0. This subtracts counts, not longest lengths or unrelated objectives.")}<p>For at most K distinct values, shrink while too many distinct values remain. After restoring validity, all suffixes starting from left through right are valid, giving ${inlineMath("r-l+1")} new ranges, where l and r are the restored boundaries. Sum that number across right endpoints. Define atMost(K)=0 for K&lt;0.</p><details id="counting-code"><summary>Count ranges with at most K distinct values</summary><pre tabindex="0" role="region" aria-label="At-most distinct range counting Python"><code>def at_most_k_distinct(nums, k):
    if type(k) is not int: raise ValueError('integer K required')
    if k &lt; 0: return 0
    counts = {}
    left = total = 0
    for right, value in enumerate(nums):
        counts[value] = counts.get(value, 0) + 1
        while len(counts) &gt; k:
            departing = nums[left]
            counts[departing] -= 1
            if counts[departing] == 0: del counts[departing]
            left += 1
        total += right - left + 1
    return total</code></pre><p>Values must be hashable. Before adding to total, counts contains exactly the positive counts in the restored window. With K=0 the range is empty, so its contribution is zero. For nonnegative integer K, subtract at_most_k_distinct(nums, K−1) from at_most_k_distinct(nums, K) to count exactly K distinct values.</p></details><p>For [1,2,1], atMost(2)=6 and atMost(1)=3, so exactly two distinct values occur in 3 ranges. Empty input contributes zero nonempty ranges. The count can grow quadratically even though computing it takes linear pointer movement.</p>`)}
${section('failure','Where forward-only boundaries fail',`<p>“Contiguous” is a recognition signal, not enough proof. For a shortest range with sum at least S, nonnegative values make sum monotone under expansion and contraction. Arbitrary signed values destroy that argument.</p><p>Counterexample: [1,−1,5], S=5. A naive shrink-while-valid sum method reaches [1,−1,5] with sum 5 and length 3, removes 1 and sees sum 4, then stops. It misses [5], length 1, because removing the next −1 would restore validity. The usual monotone argument cannot justify discarding that possibility.</p><p>Signed exact-sum counts often use prefix sums and frequency lookup. Signed shortest-threshold ranges can use ordered prefix candidates in a monotonic deque. These are different invariants, not permission to reuse the nonnegative shrink rule.</p>`)}
${section('practice','State the window and the cost model',`<p>Choose one range convention: this reader uses inclusive [left,right] for windows and half-open [l,r) for prefix queries. Define the empty state before reading length formulas. Use while when several removals may be needed; one if does not generally restore validity.</p><p>For forward-only windows, each item enters once and leaves at most once. A nested shrinking loop therefore has O(n) total moves. It has linear total work only when state updates and checks have the assumed bounded cost. Sorting adds O(n log n); iterating all centers or outer fixed values has its own larger cost.</p><p>Test empty input, k outside its domain, equal values, no feasible range, an all-valid range, a requirement with repetitions and signed-sum counterexamples. Explain what lies outside the active interval and why no lost candidate can improve the answer.</p>`)}
${section('sources','Connected patterns',`<p>${cite('https://docs.python.org/3/library/stdtypes.html#text-sequence-type-str','Python string and code-point semantics')}</p><p>These traces are new exact instructional examples, not quoted implementation diagrams.</p><p><a href="${link('algorithms/arrays')}">Stored keys and prefix state →</a> · <a href="${link('algorithms/stacks')}">Monotonic candidate reasoning →</a> · <a href="${link('algorithms/linked-lists#fast-slow')}">Cycle detection and relative motion →</a></p>`)}
`);}
windowsMeta.searchText=windowsReader(()=> '').replace(/<[^>]*>/g,' ');
export function mountWindows(scope=document){mountTopic(scope,windowsMeta.slug,article=>{mountTrace(article,'pair-lab',pairs,pairBody);mountTrace(article,'unique-lab',unique,uniqueBody);mountTrace(article,'coverage-lab',cover,coverBody);});}
